// 3 Ездри* — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Друга книга Ездри пророка, сина Сераії, сина Азарії, сина Хелкії, сина Шаллума, сина Садока, сина Ахитува,","сина Ахії, сина Финеєса, сина Ілія, сина Амарії, сина Асиєла, сина Мерайофа, сина Арна, сина Уззія, сина Ворифа, сина Авишуя, сина Финеєса, сина Єлеазара,","сина Аарона від коліна Левіїного, який був полоненим у країні Мідійській, у царювання Артаксеркса, царя Перського.","Було слово Господнє до мене:","йди і звісти народу Моєму злі діла їхні і синам їхнім — беззаконня, які вони звершили проти Мене, щоб вони сповістили синам синів своїх;","бо гріхи батьків їхніх зросли у них; забувши Мене, вони приносили жертви богам чужим.","Чи не Я вивів їх із землі Єгипетської, з дому рабства? а вони прогнівили Мене і поради Мої знехтували.","Ти обстрижи волосся голови твоєї, і кинь на них усе зле, бо вони не слухалися закону Мого — народ неприборканий!","Доки Я буду терпіти їх, яким зробив стільки благодіянь?","Заради них Я багатьох царів скинув; уразив фараона з рабами його і з усім військом його;","усіх язичників від лиця їх погубив, і на сході народ двох областей, Тира і Сидона, розсіяв і всіх ворогів їхніх знищив.","Ти ж так скажи їм: так говорить Господь:","саме Я провів вас через море і по дну його проклав вам обгороджену вулицю, дав вам вождя Мойсея й Аарона священика,","дав вам світло у стовпі вогненному, і багато чудес створив серед вас; а ви Мене забули, — говорить Господь.","Так говорить Господь Вседержитель: перепели були вам у знамення. Я дав вам стани для захисту, але ви і там нарікали","і не раділи в ім’я Моє погибелі ворогів ваших, але навіть донині ще нарікаєте.","Де ті благодіяння, які Я зробив вам? Чи не у пустелі, коли ви, зголоднівши, волали до Мене,","говорячи: «навіщо Ти привів нас у цю пустелю? уморити нас? краще нам було служити єгиптянам, ніж померти у цій пустелі»?","Я зглянувся на стогони ваші, і дав вам манну в їжу: ви їли хліб ангельський.","Коли ви відчували спрагу, чи не розсік Я камінь, і потекли води до ситости? від спеки покривав вас листями дерев.","Розділив вам землі родючі; хананеїв, ферезеїв і филистимлян вигнав від лиця вашого. Що ще зроблю вам? — говорить Господь.","Так говорить Господь Вседержитель: коли ви були у пустелі, на річці Мерри, і ті, що відчували спрагу, хулили ім’я Моє,","не вогонь послав Я на вас за богохульства, але вклав дерево у воду і ріку зробив солодкою.","Що зроблю тобі, Якове? Не хотів ти коритися, Іудо. Переселюся до інших народів і дам їм ім’я Моє, щоб дотримувалися законів Моїх.","Оскільки ви Мене залишили, то і Я залишу вас; тих, що прохають у Мене милости, не помилую.","Коли будете закликати Мене, Я не почую вас, бо ви осквернили руки ваші кров’ю, і ноги ваші швидкі на здійснення людиновбивства.","Ви ніби не Мене залишили, а вас самих, — говорить Господь.","Так говорить Господь Вседержитель: чи не Я благав вас, як батько синів і як мати дочок і як годувальниця годованців своїх,","щоб ви були Мені народом і Я вам Богом, щоб ви були Мені синами і Я вам Отцем?","Я зібрав вас, як курка пташенят своїх під крила свої. Що нині зроблю вам? Відкину вас від лиця Мого.","Коли принесете Мені приношення, відверну лице Моє від вас; бо ваші дні святкові і новомісяччя й обрізання Я відкинув.","Я послав до вас рабів Моїх, пророків; ви, схопивши їх, умертвили і розтерзали тіла їхні. Кров їхню Я стягну, — говорить Господь.","Так говорить Господь Вседержитель: дім ваш порожній. Розвію вас, як вітер полову,","і сини не будуть мати потомства, бо заповідь Мою знехтували і робили те, що є злом переді Мною.","Віддам доми ваші людям грядущим, які, не чувши Мене, увірують, які, хоч Я не показував їм знамень, виконають те, що Я заповів,","не бачивши пророків, згадають про свої беззаконня.","Заповідаю благодать людям грядущим, діти яких, не бачивши Мене очима плотськими, але духом віруючи тому, що Я сказав, торжествують з веселощами.","Отже, тепер дивися, брате, яка слава, — дивися на людей, що грядуть зі сходу,","яким Я дам у вожді Авраама, Ісаака та Якова, й Осію, і Амоса, і Михея, й Іоїля, й Авдія, й Іону,","і Наума, й Аввакума, Софонію, Аггея, Захарію і Малахію, який наречений і ангелом Господнім."],"x":{"11":"3.21.24|5.9.10","13":"1.3.10|1.14.22","15":"1.16.13|25.104.40","18":"3.14.3","19":"1.16.14|29.16.3","20":"3.20.10-11","23":"1.15.25","30":"4.30.4|4.32.11-12|50.23.37","31":"31.1.14|31.66.3"}},{"v":["Так говорить Господь: Я вивів народ цей з рабства, дав їм повеління через рабів Моїх, пророків, яких вони не захотіли слухати, але відкинули Мої поради.","Мати, яка народила їх, говорить їм: «ідіть, діти; бо я вдова і залишена.","Я виховала вас з радістю, і відпустила з плачем і гіркотою, бо ви згрішили перед Господом Богом вашим, і зробили зле перед Ним.","Нині ж що зроблю для вас? Я вдова і залишена: йдіть, діти, і просіть у Господа милости».","Тебе, Отче, прикликаю за свідка на матір синів, які не захотіли зберігати завіту мого.","Віддай їх на посоромлення і матір їхню — на розкрадання, щоб не було роду їхнього.","Нехай розсіються імена їхні по народах і згладяться на землі, бо вони знехтували завіт мій.","Горе тобі, Ассуре, що ховаєш у себе нечестивих! Роде лукавий! згадай, що Я зробив Содому і Гоморрі.","Земля їх лежить у смоляних брилах і пагорбах попелу. Так учиню Я з тими, які Мене не слухалися, — говорить Господь Вседержитель.","Так говорить Господь до Ездри: звісти народу Моєму, що Я дам їм царство Єрусалимське, яке обіцяв Ізраїлю,","і прийму славу від них і дам їм оселі вічні, які приготував для них.","Дерево життя буде для них мастю запашною; не будуть зморювані працею і не знеможуть.","Ідіть і одержіть; просіть собі днів малих, щоб вони не забарилися. Уже готове для вас царство: пильнуйте.","Свідчіть, небо і земля, бо Я стер зле і створив добре. Живу Я! — говорить Господь.","Мати! обійми синів твоїх, виховуй їх з радістю; як голубка, зміцнюй ноги їхні, бо Я обрав тебе, — говорить Господь.","І воскрешу мертвих на місцях їхніх і з гробів виведу їх, бо Я пізнав ім’я Моє в Ізраїлі.","Не бійся, мати синів, бо Я обрав тебе, — говорить Господь.","Я пошлю на допомогу тобі рабів Моїх Ісаю та Єремію, за порадою яких Я освятив і приготував тобі дванадцять дерев, обтяжених різними плодами,","і стільки ж джерел, які течуть молоком і медом, і сім гір найбільших, які вирощують троянду і лілею, через які сповню радістю синів твоїх.","Виправдай удову, дай суд бідному, допоможи убогому, захисти сироту, одягни нагого,","про розслабленого і немічного потурбуйся, з кульгавого не смійся, безрукого захисти, і сліпого приведи до бачення світла Мого,","старця і юнака у стінах твоїх збережи,","мертвих, де знайдеш, засвідчивши, віддай гробу, і Я дам тобі перше місце у Моєму воскресінні.","Відпочивай і упокоюйся, народе Мій, бо прийде спокій твій.","Годуй синів твоїх, добра годувальнице, зміцнюй ноги їхні.","З рабів, яких Я дав тобі, ніхто нехай не загине, бо Я стягну їх від тебе.","Не слабшай. Коли прийде день печалі і тісноти, інші будуть плакати і журитися, а ти будеш весела і в достатку.","Язичники будуть заздрити тобі, але нічого проти тебе зробити не зможуть, — говорить Господь.","Руки Мої покриють тебе, щоб сини твої не бачили геєни.","Утішайся, мати, з синами твоїми, бо Я спасу тебе.","Пам’ятай про синів твоїх, що спочивають. Я виведу їх з країв землі й учиню їм милість, бо Я милостивий, — говорить Господь Вседержитель.","Обійми дітей твоїх, доки Я прийду і зроблю їм милість; бо джерела Мої повні і благодать Моя не зменшиться.","Я, Ездра, одержав на горі Орив повеління від Господа йти до Ізраїля. Коли я прийшов до них, вони відкинули мене і знехтували заповідь Господню.","Тому вам говорю, язичники, що можете чути і розуміти: чекайте на Пастиря вашого, Він дасть вам мир вічний, бо близько Той, Який прийде на скінчення віку.","Будьте готові до воздаяння царства, бо світло невечірнє засяє вам на вічні часи.","Уникайте тіні віку цього; прийміть солодкість слави вашої. Я відкрито свідчу про Спасителя мого.","Ввірений дар прийміть, і насолоджуйтеся, дякуючи Тому, Хто прикликав вас у небесне царство.","Встаньте і стійте, і дивіться, яка кількість знаменованих на вечері Господній,","які, переселившись від тіні віку цього, одержали від Господа світлий одяг.","Прийми число твоє, Сионе, і прийми твоїх, одягнених у біле вбрання, які виконали закон Господній.","Число бажаних синів твоїх повне. Проси державу Господа, щоб освятився народ твій, покликаний від початку.","Я, Ездра, бачив на горі Сионській сонм великий, якого не міг перелічити, і всі вони піснями прославляли Господа.","Посеред них був юнак величний, що перевершував усіх їх, і покладав вінці на голову кожного з них і тим ще більше підносився; я вражений був здивуванням.","Тоді я запитав ангела: хто ці, господарю мій?","Він у відповідь мені сказав: це ті, які склали смертний одяг і одяглися у безсмертний і сповідали ім’я Боже; вони тепер увінчуються і приймають переможні пальми.","Я запитав: а хто цей юнак, який покладає на них вінці і вручає їм пальми?","Він відповів мені: Сам Син Божий, Якого вони прославляли у віці цьому. І я почав славити їх, які мужньо стояли за ім’я Господнє.","Тоді ангел сказав мені: йди і звісти народу моєму, які бачив ти дивні діла Господа Бога."],"x":{"8":"0.19.24","23":"18.2.7","42":"76.7.9"}},{"v":["У тридцятому році після розорення міста був я у Вавилоні, і засмучувався, лежачи на постелі моїй, і помисли входили у серце моє,","бо я бачив спустошення Сиону і багатство тих, що жили у Вавилоні.","І обурився дух мій, і я почав зі страхом говорити до Всевишнього,","і сказав: Владико Господи! Ти сказав від початку, коли єдиний заснував землю, і повелів пороху,","і дав Адаму тіло смертне, яке було також творінням рук Твоїх, і вдихнув у нього дух життя, і він зробився живим перед Тобою,","і ввів його у рай, який насадила правиця Твоя, раніше ніж земля виростила плоди;","Ти повелів йому зберігати заповідь Твою, але він порушив її, і Ти засудив його на смерть, і рід його і покоління, які народилися від нього, і племена, народи і паростки їх, яким немає числа.","Кожен народ став ходити за своїм бажанням, чинив перед Тобою діла нерозумні і нехтував заповіді Твої.","З часом Ти навів потоп на жителів землі і знищив їх,","і сповнилося на кожному з них, — як на Адамі смерть, так на цих потоп.","Одного з них Ти залишив — Ноя з родиною його, і від нього пішли всі праведні.","Коли почали розмножуватися жителі землі, і примножилися сини і народи і численні покоління, і знову почали віддаватися нечестю, більше ніж попередні,","коли почали чинити перед Тобою беззаконня: Ти обрав Собі з них мужа, якому ім’я Авраам,","і полюбив його і відкрив йому одному волю Твою,","і уклав з ним завіт вічний, і сказав йому, що ніколи не залишиш сімені його. І дав йому Ісаака, й Ісааку дав Якова та Ісава;","Ти обрав Собі Якова, Ісава ж відкинув. І примножився Яків надзвичайно.","Коли Ти вивів з Єгипту сíм’я його і привів до гори Синайської,","тоді прихилив небеса, впорядкував землю, захитав вселенну, привів у трепет безодні й увесь світ у сум’яття.","І пройшла слава Твоя в чотирьох явищах: у вогні, землетрусі, бурхливому вітрі і морозі, щоб дати закон сімені Якова і радіння роду Ізраїля,","але не відібрав у їх серця лукавого, щоб закон Твій приніс у них плід.","Із серцем лукавим перший Адам переступив заповідь, і був переможений; так і всі, що від нього пішли.","Залишилася неміч і закон у серці народу з коренем зла, і відступило добре, і залишилося лихе.","Минули часи і закінчилися літа, — і Ти воздвиг Собі раба, на ім’я Давид;","повелів йому побудувати місто імені Твоєму і в ньому приносити Тобі фіміам і жертви.","Багато років це виконувалось, і потім згрішили ті, що населяли місто,","в усьому чинячи так, як учинив Адам і всі його нащадки; бо й у них було серце лукаве.","І Ти віддав місто Твоє до рук ворогів Твоїх.","Невже краще живуть мешканці Вавилона і за це володіють Сионом?","Коли я прийшов сюди, бачив нечестя, яким немає числа, і у цьому тридцятому році полонення бачить душа моя багатьох грішників, — і знемогло серце моє,","бо я бачив, як Ти підтримуєш цих грішників і щадиш нечестивців, а народ Твій погубив, ворогів же Твоїх зберіг і не явив про те ніякого знамення.","Не розумію, як цей путь міг змінитися. Невже Вавилон чинить краще, ніж Сион?","Чи інший народ пізнав Тебе, крім Ізраїля? або які племена вірували завітам Твоїм, як Яків?","Ні винагорода їм не рівномірна, ні труд їхній не приніс плоду, бо я пройшов серед народів, і бачив, що вони живуть у достатку, хоч і не згадують про заповіді Твої.","Отже, зваж на терезах і наші беззаконня, і діла тих, що живуть на землі, і ніде не знайдеться ім’я Твоє, як тільки в Ізраїля.","Коли не грішили перед Тобою ті, що живуть на землі? або який народ так зберіг заповіді Твої?","Між цими хоч за іменами знайдеш тих, що зберігають заповіді Твої, а в інших народів не знайдеш."],"x":{"5":"0.1.27","8":"0.6.5","9":"0.7.12","11":"0.8.1","13":"0.12.3","16":"0.28.14|62.9.3","17":"1.19.2|4.4.11","23":"8.16.1|9.5.3"}},{"v":["Тоді відповів мені посланий до мене ангел, якому ім’я Уриїл,","і сказав: серце твоє занадто далеко зайшло у цьому віці, що ти помишляєш осягнути путь Всевишнього.","Я відповів: так, господарю мій. Він же сказав мені: три путі посланий я показати тобі і три подоби запропонувати тобі.","Якщо ти одну з них поясниш мені, то і я покажу тобі путь, яку бажаєш ти бачити, і навчу тебе, звідки пішло серце лукаве.","Тоді я сказав: говори, господарю мій. Він же сказав мені: йди і зваж вагу вогню, або виміряй мені подув вітру, або поверни мені день, який уже минув.","Яка людина, — відповів я, — може зробити те, чого ти вимагаєш від мене?","А він сказав мені: якби я запитав тебе, скільки осель у серці морському, або скільки джерел у самій основі безодні, або скільки жил над твердю, або які межі у раю,","ти, можливо, сказав би мені: «у безодню я не схо́див, і в пекло також, і на небо ніколи не піднімався».","Тепер же я запитав тебе тільки про вогонь, вітер і день, який ти пережив, і про те, без чого ти бути не можеш, і на це ти не відповів мені.","І сказав мені: ти і того, що твоє і з тобою від юности, не можеш пізнати;","як же сосуд твій міг би вмістити у собі путь Всевишнього і у цьому вже помітно розтлінному віці зрозуміти розтління, яке очевидне в очах моїх?","На це сказав я: краще було б нам зовсім не бути, ніж жити у нечесті і страждати, не знаючи, чому.","Він же у відповідь сказав мені: ось, я вирушив у польовий ліс, і застав дерева, що тримали раду.","Вони говорили: «прийдіть, і підемо й оголосимо війну морю, щоб воно відступило перед нами, і ми там виростимо для себе інші ліси».","Подібним чином і хвилі морські мали нараду: «прийдіть», — говорили вони, — «піднімемося і завоюємо ліси польові, щоб і там придбати для себе інше місце».","Але задум лісу виявився марним, бо прийшов вогонь і спалив його.","Подібним чином скінчився і задум хвиль морських, бо став пісок, і перешкодив їм.","Якби ти був суддею їх, кого б ти став виправдовувати або кого звинувачувати?","Справді, відповів я, задуми їх були суєтні, бо земля дана лісу, дане місце і морю, щоб носити свої хвилі.","Він же у відповідь сказав мені: справедливо розсудив ти; чому ж ти не судив таким самим чином себе самого?","Бо як земля дана лісу, а море хвилям його, так ті, що живуть на землі, можуть розуміти тільки те, що на землі; а ті, що живуть на небесах, можуть розуміти те, що на висоті небес.","І відповів я, і сказав: молю Тебе, Господи, нехай дасться мені сенс розуміння.","Не хотів я запитувати Тебе про вище, а про те, що щодня буває у нас: чому Ізраїль відданий на наругу язичникам? чому народ, який Ти полюбив, відданий нечестивим племенам, і закон батьків наших доведений до нікчемности, і писаних постанов ніде немає?","Переходимо з віку цього, як сарана, життя наше минає у страху і жаху, і ми зробилися недостойними милосердя.","Але що зробить Він з ім’ям Своїм, яке наречене на нас? ось про що я запитував.","Він же відповів мені: чим більше будеш випробовувати, тим більше будеш дивуватися; бо швидко поспішає вік цей до свого завершення,","і не може вмістити того, що обіцяно праведним у майбутні часи, бо вік цей наповнений неправдою і немочами.","А про те, що ти запитував мене, скажу тобі: посіяне зло, але ще не прийшов час викорінення його.","Тому, доки посіяне не буде вирване, і місце, на якому насіяне зло, не скасується, — не прийде місце, на якому посіяне добро.","Бо зерно злого сімені посіяне у серці Адама від початку, і скільки нечестя породило воно до цього часу і буде родити до того часу, поки не настане молотьба!","Розсуди у собі, скільки зерно злого насіння породило плодів нечестя!","Коли буде пожате незліченне колосся його, який величезний знадобиться для цього тік!","Як же і коли це буде? — запитав я його; чому наші літа малі і нещасливі?","Не поспішай підніматися, — відповів він, — вище за Всевишнього; бо марно поспішаєш бути вище за Нього: занадто далеко заходиш.","Чи не про те саме запитували душі праведних у затворах своїх, говорячи: «доки таким чином будемо ми надіятися? І коли плід нашої відплати?»","На це відповів мені Ієремиїл архангел: «коли виповниться число насінин у вас, бо Всевишній на терезах зважив вік цей,","і мірою виміряв часи, і числом обчислив години, і не посуне і не прискорить доти, доки не виповниться визначена міра».","Я ж у відповідь на це сказав йому: о, Владико Господи! а ми всі переповнені нечестям.","І, можливо, через нас не наповнюються житниці праведних, і заради гріхів тих, що живуть на землі.","На це він відповів мені: піди, запитай вагітну жінку, чи може, після виповнення дев’ятимісячного терміну, утроба її утримати у собі плід?","Я сказав: не може. Тоді він сказав мені: подібні до утроби й оселі душ у пеклі.","Як та, що народжує, поспішає народити, щоб звільнитися від болістей народження, так і ці поспішають віддати ввірене їм.","Спочатку буде показане тобі те, що ти бажаєш бачити.","Якщо я знайшов благодать перед очима твоїми, — відповів я, — і якщо це можливо і я здатний до того,","покажи мені: чи більше те, що має прийти, за те, що минуло, чи те, що відбулося, більше за те, що буде?","Що минуло, я це знаю, а що прийде, не відаю.","Він сказав мені: стань праворуч, і я поясню тобі значення подобою.","І я став, і побачив: ось розпалена піч проходить переді мною; і коли полум’я пройшло, я побачив: залишився дим.","Після цього пройшла переді мною хмара, наповнена водою, і пролився з неї сильний дощ; але як тільки стрімкість дощу припинилася, залишилися краплі.","Тоді він сказав мені: розмірковуй про себе: як дощ більший за краплі, а вогонь більший за дим, так міра минулого перевищила, а залишилися краплі і дим.","Тоді я благав його і сказав: чи думаєш ти, що я доживу до цих днів? і що буде у ці дні?","На це відповів він, і сказав: про знамення, про які ти запитуєш мене, я частково можу сказати тобі, а про життя твоє я не посланий говорити з тобою, та й не знаю."],"x":{"13":"6.9.8|13.25.18"}},{"v":["Про знамення: ось, настануть дні, в які багато хто з тих, що живуть на землі, які володіють віданням, будуть захоплені, і шлях істини сховається, і вселенна збідніє вірою,","і примножиться неправда, яку тепер ти бачиш і про яку здавна чув.","І буде, що країна, яку ти тепер бачиш панівною, піддасться спустошенню.","А якщо Всевишній дасть тобі дожити, то побачиш, що після третьої труби раптово засяє серед ночі сонце і місяць тричі на день;","і з дерева буде капати кров, камінь подасть голос свій, і народи похитнуться.","Тоді буде царювати той, якого ті, що живуть на землі, не очікують, і птахи перелетять на інші місця.","Море Содомське вивергне риб, буде подавати вночі голос, невідомий для багатьох; однак же усі почують голос його.","Буде сум’яття у багатьох місцях, часто буде посилатися з неба вогонь; дикі звірі перемінять місця свої, і нечисті жінки будуть народжувати чудовиськ.","Солодкі води зробляться солоними, і всі друзі повстануть одне проти одного; тоді сховається розум, і розуміння відійде у своє сховище.","Багато хто буде шукати його, але не знайде, і збільшиться на землі неправда і нестриманість.","Одна область буде запитувати іншу сусідню: «чи не проходила по тобі правда, яка робить праведним?» І та скаже: «ні».","Люди у той час будуть сподіватися, і не досягнуть бажаного, будуть трудитися, і не управляться путі їхні.","Про ці знамення мені дозволено сказати тобі, і якщо знову помолишся і поплачеш, як тепер, і попостишся сім днів, то почуєш ще більше за те.","І я отямився, і тіло моє сильно тремтіло, і душа моя знемогла, ніби зникала.","Але ангел, який прийшов до мене, підтримав мене й укріпив мене, і поставив на ноги.","І було, у другу ніч прийшов до мене Салафиїл, вождь народу, і запитав мене: де ти був, і від чого лице твоє таке сумне?","Хіба не знаєш, що тобі довірений Ізраїль у країні переселення його?","Отже, встань і споживи хліба, і не залишай нас, як пастир свого стада, у руках лукавих вовків.","Тоді сказав я йому: відійди від мене, і не наближайся до мене. І він, почувши це, відійшов від мене.","А я сім днів постився, стогнучи і плачучи, як повелів мені ангел Уриїл.","І після семи днів помисли серця мого знову були для мене вкрай обтяжливими;","але душа моя отримала дух розуміння, і я знову почав говорити перед Всевишнім","і сказав: о, Владико Господи! Ти з усіх лісів на землі і з усіх дерев на ній обрав тільки одну виноградну лозу;","Ти з усього кола земного обрав Собі одну печеру, і з усіх квітів у вселенній Ти обрав Собі одну лілею;","Ти з усіх безодень морських наповнив для Себе одне джерело, а з усіх побудованих міст освятив для Себе один Сион.","З усіх створених птахів Ти найменував для Себе одну голубицю, і з усіх створених тварин Ти обрав Собі одну вівцю;","із усіх численних народів Ти придбав Собі один народ, і полюбив його, дав йому закон довершений.","Але нині, Господи, чому ж Ти віддав одного багатьом, і на одному корені Ти насадив інші паростки і розсіяв Твій єдиний народ між багатьма народами?","І потоптали його супротивники, які обітницям Твоїм і завітам Твоїм не вірували.","І якщо вже Ти сильно зненавидів народ Твій, те нехай би він Твоїми руками карався.","Коли я промовляв слова ці, посланий був до мене ангел, який приходив до мене раніше уночі,","і сказав мені: послухай мене, і я навчу тебе; слухай мене, і я скажу тобі ще більше.","Говори, сказав я, господарю мій. І він сказав мені: ти занадто далеко зайшов допитливістю розуму твого про Ізраїль; невже ти більше любиш його, ніж Той, Який створив його?","Ні, господарю мій, відповів я, але говорив від великої скорботи. Нутрощі мої мучать мене весь час, коли я намагаюся осягнути шлях Всевишнього і зрозуміти хоч частину суду Його.","Він відповів: не можеш. Чому ж, господарю мій? — запитав я. Краще б я не народився, й утроба материнська зробилася для мене гробом, ніж бачити гноблення Якова і виснаження роду Ізраїльського.","І він сказав мені: обчисли мені те, що ще не прийшло, і збери мені розсіяні краплі, й оживи засохлі квіти;","відкрий закриті сховища і виведи мені закриті у них вітри, і покажи мені образ голосу: і тоді я покажу тобі те, що ти намагаєшся бачити.","Владико Господи! — відповів я, — хто може знати це, хіба тільки той, хто не живе з людьми?","А я безумний, і як можу говорити про те, про що Ти запитав мене?","Тоді Він сказав мені: як ти не можеш зробити нічого зі сказаного, так не можеш пізнати провидіння Мого, ні межі любови, яку обіцяв Я народу. —","Але ось, Господи, Ти близький до тих, які наближаються до кінця, і що будуть робити ті, які раніше мене були, або ми, або які після нас будуть?","Він сказав мені: до вінця уподібню я суд Мій; як немає запізнення останніх, так і прискорення перших.","Відповів я і сказав: чи не міг би Ти з’єднати в єдине як тих, які створені були раніше, так і тих, які існують і які будуть, щоб скоріше оголосити їм суд Твій?","Він відповів мені: не може прискорити творіння Творця свого, ні вік цей не може вмістити у собі всіх разом, які повинні бути створені.","І сказав я: як же Ти сказав рабу Твоєму, що Ти дав життя створеному творінню вкупі, і однак творіння витримало це; тому могли б понести і ті, що нині існують, вкупі.","Він сказав мені: запитай жінку, і скажи їй: «якщо ти народжуєш десять, то чому народжуєш за часом?», і проси її, щоб вона народила десять разом.","Я ж сказав Йому: неможливо це, але має бути за часом.","Тоді Він сказав мені: і Я дав надрам землі здатність посіяне на ній вирощувати за часом.","Як немовля не може робити того, що властиво старцям, так Я упорядкував створений Мною вік.","Тоді я запитав Його і сказав: коли Ти відкрив мені путь, то дозволь мені сказати Тобі: мати наша, про яку Ти говорив мені, чи молода ще, чи наближається до старости?","Запитай про це ту, яка народжує, і вона скаже тобі.","Скажи їй: «чому народжені тобою нині не подібні до тих, які народжені були колись, але менші за них на зріст?»","І вона скаже тобі: «одні народжені мною у міцності молодої сили, а інші народжені на старість, коли утроба почала втрачати свою силу».","Розміркуй же ти: ви тепер менші за станом, ніж ті, які були перед вами;","і ті, які після вас народяться, будуть ще менші за вас, тому що творіння уже постаріло, і сила юнака уже минула.","І сказав я: якщо я придбав благовоління перед очима Твоїми, покажи рабові Твоєму, через кого Ти відвідуєш творіння Твоє?"]},{"v":["І сказав Він мені: від початку творіння кола земного і раніше ніж установлені були межі віку, і раніше ніж подули вітри;","раніше ніж почутий був голос грому, раніше ніж заблищала блискавка, раніше ніж утвердилися основи раю;","раніше ніж з’явилися прекрасні квіти, раніше ніж утвердилися сили рухів, і раніше ніж зібралися незліченні воїнства ангелів;","раніше ніж піднялися висоти повітряні, раніше ніж визначилися міри тверді, раніше ніж запалали вогні на Сионі;","раніше ніж досліджені були літа, і відокремлені ті, які грішать нині, і відзначені ті, які зберігали віру, як скарб:","тоді Я помислив, і створено було все Мною одним, а не через будь-кого іншого; від Мене також прийде і кінець, а не від будь-кого іншого.","Тоді я відповів: який поділ часів, і коли буде кінець першого і початок останнього?","Від Авраама навіть до Ісаака, коли народилися від нього Яків та Ісав, рука Якова тримала від початку п’яту́ Ісава.","Кінець цього віку — Ісав, а початок наступного — Яків.","Рука людини — початок її, а кінець — п’ята її. Про інше, Ездро, не запитуй Мене.","Я ж у відповідь сказав Йому: о, Владико Господи! якщо я знайшов благодать перед очима Твоїми,","молю Тебе, покажи рабові Твоєму кінець знамень Твоїх, частину яких показав Ти мені минулої ночі.","Він відповів мені і сказав: встань на ноги твої, і слухай голос, сповнений шуму,","і буде ніби землетрус, але місце, на якому ти стоїш, не захитається.","Тому, коли буде говорити, ти не жахайся; бо про кінець буде слово, і основи землі маються на увазі.","А оскільки йдеться про них самих, то земля затремтить і похитнеться, бо знає, що кінець їх повинен змінитися.","І було, коли я почув голос, встав на ноги мої, і чув, і ось голос, який говорить, і шум його, як шум вод многих,","і сказав: ось, настають дні, коли Я почну наближатися, щоб відвідати тих, що живуть на землі,","коли почну Я стягувати з тих, які неправдою своєю зробили неправедно велику шкоду, і коли виповниться міра приниження Сиону.","А коли назнаменується вік, який почне проходити, то ось знамення, які Я покажу: книги розкриються перед лицем тве́рди, й усі разом побачать;","і однолітні немовлята заговорять своїми голосами, і вагітні жінки будуть народжувати недозрілих немовлят через три і чотири місяці, і вони залишаться живими і зміцняться;","засіяні поля раптово стануть ніби незасіяними, і повні житниці виявляться порожніми;","потім засурмить труба з шумом, і коли почують її, всі раптово жахнуться.","І буде у той час, озброяться друзі проти друзів, як вороги, й устрашиться земля з тими, що живуть на ній, і жи́ли джерел зупиняться і три години не будуть текти.","Усякий, хто після всього цього, про що Я передрік тобі, залишиться у живих, сам спасеться, і побачить спасіння Моє і кінець вашого віку.","І побачать люди обрані, які не зазнали смерти від народження свого, і зміниться серце тих, що живуть, і перетвориться на почуття інше.","Бо зло знищиться, і зникне лукавство;","процвіте віра, переможене буде розтління, явиться істина, яка стільки часу залишалася без плоду.","Коли Він говорив, я глянув на того, перед яким стояв.","І він сказав мені: я прийшов показати тобі час грядущої ночі.","Отже, якщо ти знову помолишся і знову сім днів будеш поститися, то я покажу тобі більше у день, в який я почув тебе.","Голос твій почутий у Всевишнього; побачив Сильний правильну дію, побачив і чистоту, яку зберігав ти від юности твоєї.","Тому Він послав мене показати тобі все це і сказати: уповай і не бійся;","не поспішай у перші часи помишляти суєтне, щоб не судити тобі з таким самим поспіхом про часи останні.","Після цього я знову зі сльозами молився, і також постився сім днів, щоб виконати три седмиці, заповідані мені.","У восьму ж ніч серце моє прийшло знову у збудження, і я почав говорити перед Всевишнім,","бо дух мій запалав сильно, і душа моя томилася.","І сказав я: Господи! Ти від початку творіння говорив; у перший день сказав: «нехай буде небо і земля», і слово Твоє було звершеним ділом.","Тоді носився Дух, і темрява облягала навколо і мовчання: звуку людського голосу ще не було.","Тоді повелів Ти зі скарбниць Твоїх вийти яскравому світлу, щоб явилося діло Твоє.","У другий день створив Ти дух тверди і повелів йому відокремити і зробити поділ між водами, щоб деяка частина їх піднялася вгору, а інша залишилася внизу.","У третій день Ти повелів водам зібратися на сьомій частині землі, а шість частин висушив, щоб вони служили перед Тобою для засівання й оброблення.","Слово Твоє виходило, і негайно ставало ділом;","раптово явилася безмірна кількість плодів і різноманітні приємності для смаку, квіти виглядом своїм незмінні, з запахом, невимовно запашним: усе це звершено було у третій день.","У четвертий день Ти повелів бути сяйву сонця, світлу місяця, розташуванню зірок,","і повелів, щоб вони служили людині, яка має бути створеною.","У п’ятий день Ти сказав сьомій частині, в якій була зібрана вода, щоб вона породила тварин, тих, що літають, і риб, що і сталося.","Вода німа і бездушна, за помахом Божим, породила тварин, щоб усі роди сповіщали про дивні діла Твої.","Тоді Ти зберіг двох тварин: одна називалася бегемотом, а інша левіафаном.","І Ти відокремив їх одне від одного, бо сьома частина, де була зібрана вода, не могла прийняти їх разом.","Бегемоту Ти дав одну частину з землі, осушеної на третій день, нехай живе у ній, в якій тисячі гір.","Левіафану дав сьому частину водяну, і зберіг його, щоб він був споживою тим, кому Ти хочеш, і коли хочеш.","У шостий же день повелів Ти землі породити перед Тобою худобу, звірів і плазунів;","а після їх Ти створив Адама, якого поставив володарем над усіма Твоїми тварями і від якого походимо всі ми і народ, який Ти обрав.","Усе це сказав я перед Тобою, Господи, тому що для нас створив Ти вік цей.","Про інші ж народи, які народилися від Адама, Ти сказав, що вони ніщо, але подібні до слини, і всю безліч їх Ти уподібнив краплям, що крапають із посудини.","І нині, Господи, ось, ці народи, за ніщо Тобою визнані, почали володарювати над нами і пожирати нас.","Ми ж, народ Твій, який Ти назвав Твоїм первістком, єдинородним, улюбленим Твоїм, віддані у руки їх.","Якщо для нас створений вік цей, то чому не одержуємо ми спадщини з віком? І доки це?"]},{"v":["Коли я закінчив говорити ці слова, посланий був до мене ангел, який посилався до мене у попередні ночі,","і сказав мені: встань, Ездро, і слухай слова́, які я прийшов говорити тобі.","Я сказав: говори, господарю мій. І він сказав мені: море розташоване у просторому місці, щоб бути глибоким і безмірним;","але вхід у нього знаходиться у вузькому місці, так що подібний до рік.","Хто побажав би ввійти у море і бачити його, або володарювати над ним, той, якщо не пройде вузьке, як може дійти до широти?","Або інша подоба: місто побудоване і розташоване на рівнині, й наповнене усіма благами;","але вхід у нього тісний і розташований на крутизні так, що праворуч вогонь, а ліворуч глибока вода.","Між ними, тобто між вогнем і водою, лежить лише одна стежка, на якій може поміститися не більше, як тільки ступня людини.","Якщо місто це буде дане у спадщину людині, то як вона одержить свою спадщину, якщо ніколи не перейде небезпеки, що лежить на шляху?","Я сказав: так, Господи. І Він сказав мені: така і доля Ізраїля.","Для них Я створив вік; але коли Адам порушив Мої постанови, визначено було бути тому, що зроблено.","І зробилися входи віку цього тісними, хворобливими, стомливими, також вузькими, лукавими, сповненими бід і які потребують великої праці.","А входи майбутнього віку просторі, безпечні, і приносять плід безсмертя.","Отже, якщо ті, що входять, які живуть, не ввійдуть у це тісне і злигоднє, вони не можуть одержати те, що уготоване.","Навіщо ж засмучуєшся, коли ти тлінний, і чого бентежишся, коли смертний?","Навіщо прийняв ти у серці твоєму того, що майбутнє, а прийняв те, що у теперішньому?","Я відповів і сказав: Владико Господи! ось, Ти визначив законом Твоїм, що праведники успадкують це, а грішники загинуть.","Праведники потерплять тісноту, сподіваючись на просторе, а ті, що нечестиво жили, хоч потерпіли тісноту, не побачать просторого.","І Він сказав мені: немає судді вище за Бога, немає того, хто розуміє більше за Всевишнього.","Гине багато хто у цьому житті, тому що не дбає про запропонований йому закон Божий.","Бо суворо повелів Бог тим, що приходять, коли вони прийшли, що працюючи, вони будуть живі, і що дотримуючись, не будуть покарані.","А вони не послухалися, і стали проти Нього, утвердили у собі помисел суєтний.","Захопилися гріховними оманами, сказали про Всевишнього, що Його нема, не пізнали путів Його,","знехтували закон Його, відкинули обітниці Його, не мали віри до обрядових установлень Його, не звершували діл Його.","І тому, Ездро, пустим порожнє, а повним повне.","Ось, прийде час, коли прийдуть знамення, які Я передрік тобі, і явиться наречена, і, являючись, покажеться, — приховувана нині землею.","І всякий, хто позбавиться раніше перелічених зол, сам побачить чудеса Мої.","Бо відкриється Син Мій Ісус з тими, які з Ним, і ті, що залишилися, будуть насолоджуватися чотириста років.","А після цих років помре Син Мій Христос і всі люди, які мають дихання.","І повернеться вік у давнє мовчання на сім днів, подібно до того, як було раніше, так що не залишиться нікого.","Після ж семи днів постане вік приспаний, і помре ушкоджений.","І віддасть земля тих, які у ній сплять, і прах тих, які мовчазно у ньому живуть, а сховища віддадуть ввірені їм душі.","Тоді явиться Всевишній на престолі суду, і пройдуть біди, і закінчиться довготерпіння.","Суд буде один, істина утвердиться, віра зміцниться.","Потім піде діло, відкриється нагорода, постане правда, перестане господарювати неправда.","Я сказав: Авраам перший молився за содомлян; Мойсей — за батьків, які згрішили у пустелі;","Ісус після нього — за Ізраїля у дні Ахана;","Самуїл і Давид — за тих, кого погубляють, Соломон — за тих, які прийшли на освячення;","Ілля — за тих, які прийняли дощ, і за мерця, щоб він ожив;","Єзекія — за народ у дні Сеннахирима, і багато хто — за багатьох.","Отже, якщо тоді, коли посилилося розтління і примножилася неправда, праведні молилися за неправедних, то чому ж не бути тому і нині?","Він відповів мені і сказав: нинішній вік не є кінець; слави у ньому часто не буває, тому молилися за немічних.","День же суду буде кінцем часу цього і початком часу майбутнього безсмертя, коли мине тління,","припиниться нестриманість, знищиться невір’я, а зросте правда, засяє істина.","Тоді ніхто не зможе ні спасти загиблого, ні погубити того, хто переміг.","Я відповів і сказав: ось моє слово перше й останнє: краще було не давати землі Адаму, або, коли вже дана, утримати його, щоб не згрішив.","Яка користь людям — у нинішньому віці жити у смутку, а після смерти очікувати покарання?","О, що зробив ти, Адаме? Коли ти згрішив, то звершилося падіння не тебе тільки одного, але і нас, які від тебе народжуємося.","Яка користь нам, якщо нам обіцяно безсмертний час, а ми чинили смертні діла?","Нам передвіщена вічна надія, а ми, непотребні, зробилися суєтними.","Нам уготовані оселі здоров’я і спокою, а ми жили зле;","уготована слава Всевишнього, щоб покрити тих, які жили лагідно, а ми ходили путями злими.","Показаний буде рай, плід якого перебуває нетлінним і в якому спокій і зцілення;","але ми не увійдемо в нього, тому що оберталися у місцях неплідних.","Світліше за зірки засяють лиця тих, які мали стриманість, а наші лиця — чорніші за пітьму.","Ми не помишляли у житті, коли чинили беззаконня, що після смерти будемо страждати.","Він відповів і сказав: це — помисел про боротьбу, яку повинна вести на землі народжена людина,","щоб, якщо буде переможена, потерпіти те, про що ти сказав, а якщо переможе, одержати те, про що Я говорю.","Це те життя, про яке сказав Мойсей, коли жив, до народу, говорячи: «обери собі життя, щоб жити».","Але вони не повірили йому, ні пророкам після нього, ні Мені, що говорив до них,","що не буде скорботи за погибель їх, як буде радість за тих, яким уготовано спасіння.","Я відповів і сказав: знаю, Господи, що Всевишній називається милосердим, тому що помилує тих, які ще не прийшли у світ,","і милує тих, які проводять життя у законі Його.","Він довготерпеливий, бо виявляє довготерпіння до тих, що згрішили, як до Свого творіння.","Він щедрий, бо готовий давати за потребою,","і многомилостивий, бо примножує милості Свої до тих, що живуть нині, і до тих, що жили, і до тих, що будуть жити.","Бо, якби не примножував Він Своїх милостей, то не міг би вік продовжувати жити з тими, які живуть у ньому.","Він подає дари; бо якби не дарував з благости Своєї, щоб полегшити тим, що зробили нечестя своїми беззаконнями, то не могла б залишатися у живих десятитисячна частина людей.","Він суддя, і якби не прощав тих, які створені словом Його, і не знищив безлічі злочинів,","можливо, з незліченної кількости залишився б тільки дуже мало хто."],"x":{"21":"4.8.1","38":"10.8.23:30|13.6.14","39":"10.17.21-22","58":"76.2.7"}},{"v":["Він відповів мені і сказав: цей вік Всевишній створив для багатьох, а майбутній для небагатьох.","Скажу тобі, Ездро, подобу. Як коли запитаєш землю, вона скаже тобі, що дає дуже багато речовини, з якої робляться глиняні речі, а не багато пороху, з якого буває золото, так і діла нинішнього віку.","Багато хто створений, але небагато спасеться.","Я відповів і сказав: душе́! пожери сенс і поглинь мудрість.","Бо ти обіцяла слухати, і побажала пророкувати, а тобі дано час тільки, щоб жити.","О, Господи! невже Ти не дозволиш рабу Твоєму, щоб ми молилися перед Тобою про дарування серцю нашому сімені й розуму обробляти, щоб народився плід, яким міг би жити всякий розтлінний, хто буде носити ім’я людини?","Ти єдиний, і ми єдине творіння рук Твоїх, як сказав Ти.","І як же нині в утробі материнській утворюється тіло, і Ти даєш члени, як зберігається Твоє творіння у вогні й воді, і як дев’ять місяців терпить у собі Твоє ж створіння Твою твар, яка у ньому створена?","І те, що зберігає, і те, що зберігається, і те й інше зберігаються, й утроба матері у свій час віддає те збережене, що у ній виросло.","Ти повелів із самих членів, тобто із сосків, давати молоко, плід сосків,","нехай годується створене до деякого часу, а після передаси його Твоєму милосердю.","Ти виховав його Твоєю правдою, навчив його Твого закону, настановив його Твоїм розумом,","і умертвиш його, як Твоє творіння, і знову оживиш, як Твоє діло.","Якщо Ти погубиш створене з таким піклуванням, то повелінню Твоєму легко влаштувати, щоб і зберігалося те, що було створено.","І нині, Господи, я скажу: про всяку людину Ти більше знаєш; але скажу про народ Твій, за який уболіваю,","про спадщину Твою, за яку проливаю сльози, про Ізраїля, за якого болію серцем, про Якова, про якого тужу.","Почну молитися перед Тобою за себе і за них, бо бачу гріхопадіння нас, які живуть на землі.","Але я чув, що скоро прийде Суддя.","Тому почуй мій голос, прислухайся до слів моїх, і я буду говорити перед Тобою. [Початок слів Ездри, перш ніж він був узятий.]","Я сказав: Господи, що живеш вічно, Якого очі звернені на піднесене і небесне,","Якого престіл неоціненний і слава незбагненна, Якому з трепетом предстоять воїнства ангелів, що служать у вітрі і вогні, Якого слово істинне і глаголи непорушні,","повеління сильне і правління страшне, Якого погляд висушує безодні, гнів розплавляє гори й істина перебуває повік!","Почуй молитву раба Твого, і послухай моління створіння Твого.","Доки живу, буду говорити, і доки розумію, буду відповідати. Не дивися на гріхи народу Твого, але на тих, які Тобі в істині служать;","не звертай уваги на нечестиві діла язичників, але на тих, які завіти Твої зберегли серед бід;","не помишляй про тих, які перед Тобою неправдиво чинили, але пом’яни тих, які, з волі Твоєї, пізнали страх;","не погубляй тих, які жили, як тварини, але споглянь на тих, які ясно навчали закону Твого;","не прогнівайся на тих, які визнані гіршими за звірів;","але полюби тих, які завжди надіються на правду Твою і славу.","Бо ми і батьки наші на такі хвороби страждаємо;","а Ти, заради нас — грішних, назвешся милосердим.","Якщо Ти побажаєш помилувати нас, то назвешся милосердим, тому що ми не маємо діл правди.","Праведники ж, у яких багато діл придбано, за власні діла одержать винагороду.","Що́ є людина, щоб Ти гнівався на неї, і рід розтлінний, щоб Ти стільки засмучувався ним?","Воістину, немає нікого з народжених, хто не вчинив би нечестиво, і з тих, які сповідують Тебе, немає нікого, хто не згрішив би.","У тім-то і звіститься правда Твоя і благість Твоя, Господи, коли помилуєш тих, які не мають сутности добрих діл.","Він відповів мені і сказав: справедливо ти сказав дещо, і за словами твоїми так і буде.","Бо істинно не помишляю Я про діла тих створінь, які згрішили, раніше смерти, раніше суду, раніше загибелі;","але насолоджуюся подвигами праведних, і згадую, як вони подорожували, як спасалися і намагалися заслужити нагороду.","Як сказав Я, так і є.","Як хлібороб сіє на землі багато насіння і садить багато рослин, але не все посіяне збережеться з часом, і не все посаджене укоріниться, так і ті, які посіяні у віці цьому, не усі спасуться.","Я відповів і сказав: якщо я знайшов благодать, то буду говорити.","Як насіння хлібороба, якщо не зійде, або не прийме вчасно дощу Твого, або пошкодиться від надміру дощів, гине:","так і людина, створена руками Твоїми, — і Ти називаєшся її первообразом, тому що Ти подібний до неї, для якої створив усе і яку Ти уподібнив до насіння хлібороба.","Не гнівайся на нас, але пощади народ Твій і помилуй спадщину Твою, — а Ти милосердий до створіння Твого.","Він відповів мені і сказав: теперішнє теперішнім і майбутнє майбутнім.","Багато чого не вистачає тобі, щоб ти міг полюбити створіння Моє більше за Мене, хоч Я часто наближався до тебе самого, а до неправедних ніколи.","Але й у тім дивний ти перед Всевишнім,","що смирив себе, як пристойно тобі, і не судив про себе так, щоб багато славитися між праведними.","Многі і гіркі біди спіткають тих, які населяють вік, останнім часом, тому що вони ходили у великій гордині.","А ти дбай про себе, і подібним до тебе шукай слави;","бо вам відкритий рай, насаджене дерево життя, призначений майбутній час, готовий достаток, побудоване місто, приготований спокій, довершена благість і довершена премудрість.","Корінь зла запечатаний від вас, неміч і тління сховані від вас, і розтління біжить у пекло в забуття.","Минули хвороби, і наприкінці показався скарб безсмертя.","Не намагайся більше дізнатися про безліч загиблих.","Бо вони, одержавши свободу, знехтували Всевишнього, зневажили закон Його і залишили путі Його,","а ще і праведних Його потоптали,","і говорили у серці своєму: «немає Бога», хоч і знали, що вони смертні.","Як на вас очікує те, про що сказано раніше, так і їх — спрага і муки, які приготовані. Бог не хотів погубити людину,","але самі створені знеславили ім’я Того, Хто створив їх, і були невдячними до Того, Хто наперед уготував їм життя.","Тому суд Мій нині наближається, —","про що Я не всім відкрив, а тільки тобі і небагатьом, до тебе подібним. Я відповів і сказав:","ось нині, Господи, Ти показав мені безліч знамень, які Ти почнеш творити при кончині, але не показав, у який час."],"x":{"35":"10.8.46|13.6.36","58":"25.52.2"}},{"v":["Він відповів мені і сказав: вимірюючи, вимірюй час у собі самому, і коли побачиш, що пройшла деяка частина знамень, раніше вказаних,","тоді зрозумієш, що це і є той час, в який почне Всевишній відвідувати вік, Ним створений.","Коли виявиться у віці коливання місць, сум’яття народів,","тоді зрозумієш, що про це говорив Всевишній від днів, що були раніше за тебе, від початку.","Як усе, створене у віці, має початок, так само і кінець, і закінчення буває явно:","так і часи Всевишнього мають початки, які відкриваються чудесами і силами, і закінчення, які виявляються діями і знаменнями.","Усякий, хто спасеться і зможе ділами своїми і вірою, якою віруєте, уникнути раніше провіщених бід,","залишиться, і побачить спасіння Моє на землі Моїй і в межах Моїх, які Я освятив Собі від віку.","Тоді пошкодують ті, що відступили нині від шляхів Моїх, і ті, що відкинули їх із презирством, будуть перебувати у муках.","Ті, які не пізнали Мене, одержуючи за життя благодіяння,","і погребували законом Моїм, не зрозуміли його, але знехтували, коли ще мали свободу і коли ще відкрито було їм місце для покаяння,","ті пізнають Мене після смерти у муках.","Ти не цікався більше, як нечестиві будуть мучитися, але досліджуй, як спасуться праведні, яким належить вік і заради яких вік, і коли.","Я відповів і сказав:","я раніше говорив, і тепер говорю, і потім буду говорити, що більше тих, які загинуть, ніж тих, які спасуться, як хвиля більша за краплю.","Він відповів мені і сказав:","яка нива, таке і насіння; які квіти, такі і кольори; який діяч, таке і діло; який хлібороб, такий і обробіток; бо то був час віку.","Коли Я уготовляв вік, перше ніж він був, для перебування тих, які живуть нині у ньому, ніхто Мені не суперечив.","А нині, коли вік цей був створений, норови створених пошкодилися при жнивах, які не зменшуються, при недослідимому законі.","І розглянув Я вік, і ось, виявилася небезпека від задумів, які з’явилися у ньому.","Я побачив і пощадив його, і зберіг для Себе одну ягоду з виноградного грона й одне насадження з безлічі.","Нехай загине безліч, що дарма народилася, і збережеться ягода Моя і насадження Моє, яке Я виростив з великим трудом.","А ти, коли після семи днів інших, не постячись, однак, у них,","вийдеш на квітуче поле, де немає побудованого дому, і станеш годуватися тільки від польових квітів і не споживати м’яса, ні пити вина, а тільки квіти,","молися до Всевишнього безперестанно, і Я прийду і буду говорити з тобою.","І пішов я, як Він сказав мені, на поле, яке називається Ардаф, і сів там у квітах і споживав від польових трав, і була мені їжа від них насиченням.","Після семи днів лежав я на траві, і серце моє знову бентежилось, як раніше.","І відкрилися вуста мої, і я почав говорити перед Всевишнім і сказав:","о, Господи! являючи Себе нам, Ти явився батькам нашим у пустелі непрохідній і неплідній, коли вони вийшли з Єгипту,","і сказав: «слухай Мене, Ізраїлю, і дослухайся до слів Моїх, сíм’я Якова.","Ось, Я сію у вас закон Мій, і принесе у вас плід, і ви будете славитися у ньому вічно».","Але батьки наші, прийнявши закон, не виконали його і постанов Твоїх не зберегли, і хоча плід закону Твого не загинув і не міг загинути, тому що був Твій,","але ті, що прийняли закон, загинули, не зберігши того, що у ньому було посіяно.","Зазвичай буває, що коли земля прийняла насіння, або море корабель, або яка-небудь посудина їжу або питво, і якщо буде пошкоджене те, у чому посіяно, або те, у чому вміщено,","у такому випадку гине разом і саме посіяне, або вміщене, або прийняте, і прийнятого вже не залишається перед нами. Але з нами не так.","Ми, що прийняли закон, згрішивши, загинули, так само і серце наше, яке прийняло його;","Але закон не загинув, і залишається у своїй силі.","Коли я говорив це у серці моєму, я споглянув очима моїми, і побачив з правого боку жінку; і ось, вона плакала і ридала великим воланням, і сильно уболівала душею; одяг її був розідраний, а на голові її попіл.","Тоді залишив я розмірковування, якими був зайнятий, і, звернувшись до неї, сказав їй:","про що плачеш ти, і чого так уболіваєш душею?","Вона сказала: залиш мене, господарю мій, нехай пла́чу за себе і подвою скорботу, бо я дуже засмучена душею і дуже принижена.","Я запитав її: що потерпіла ти? скажи мені. І вона відповіла мені:","я була неплідна, раба твоя, і не народжувала, маючи чоловіка, тридцять років.","Кожної години, кожного дня у ці тридцять років я молила Всевишнього безперестанно,","і почув мене Бог, рабу твою, після тридцяти років, побачив смирення моє, дослухався до скорботи моєї і дав мені сина, і я дуже зраділа йому, і чоловік мій, і всі співгромадяни мої, і ми багато прославляли Всевишнього.","Я вигодувала його з великим трудом,","і коли він виріс і пішов узяти собі дружину, я влаштувала день бенкету."]},{"v":["Але коли син мій увійшов у шлюбний чертог свій, він упав, і помер.","І перекинули всі ми світильники, і всі співгромадяни мої піднялися утішати мене, і я спочила до ночі другого дня.","Коли ж усі перестали утішати мене, щоб залишити мене у спокої, я, уставши вночі, побігла і прийшла, як бачиш, на це поле.","І думаю вже не повертатися у місто, але залишатися тут, не їсти, не пити, але безперестанно плакати і поститися, доки не помру.","Залишивши розмірковування, якими займався, я з гнівом відповів їй і сказав:","о, найбезумніша з усіх жон! чи не бачиш скорботи нашої і що сталося з нами —","що Сион, мати наша, засмучується безмірно, вкрай принижена, і плаче гірко?","І тепер, коли всі ми уболіваємо і засмучуємося, тому що всі засмучені, чи будеш ти засмучуватися через одного сина твого?","Запитай землю, і вона скаже тобі, що їй-то слід оплакувати падіння такої безлічі, що народжується на ній;","бо всі народжені з неї від початку й інші, які мають народитися, ледь не усі гинуть, і така безліч їх віддається на знищення.","Отже, хто повинен більше засмучуватися, як не та, яка втратила таку безліч, а не ти, що уболіваєш за одного?","Якщо ти скажеш мені: «плач мій не подібний до плачу землі, бо я втратила плід утроби моєї, який я носила із сумом і народила у болістях;","а земля — за властивістю землі; на ній теперішня безліч як відходить, так і приходить»:","і я скажу тобі, що як ти з трудом народила, так і земля дає плід свій людині, яка від початку обробляє її.","Тому утримайся тепер від скорботи твоєї і мужньо перенось втрату, що трапилася у тебе.","Бо якщо ти визнаєш праведним визначення Боже, то у свій час одержиш сина, і між дружинами будеш прославлена.","Отже, повернися у місто до чоловіка твого.","Але вона сказала: не зроблю так, не повернуся в місто, але тут помру.","Продовжуючи говорити з нею, я сказав:","не роби цього, але послухай пораду мою. Бо скільки бід Сиону? Утішся заради скорботи Єрусалима.","Бо ти бачиш, що святилище наше спустошене, вівтар наш скинутий, храм наш зруйнований,","псалтир наш принижений, пісні замовкли, радість наша зникла, світло світильника нашого погасло, ковчег завіту нашого розкрадений, Святе наше осквернене, й ім’я, наречене на нас, ледь не зганьблене, діти наші потерпіли знеславлення, священики наші побиті, левити наші відведені у полон, дівчата наші осквернені, дружини наші потерпіли насильство, праведники наші захоплені, отроки наші загинули, юнаки наші у рабстві, сильні наші знемогли;","і що з усього найтяжче, знамено Сиону позбавлене слави своєї, бо віддане у руки ненависників наших.","Тому залиш великий сум твій, і відклади безліч скорбот, щоб помилував тебе Кріпкий, і Всевишній дарував тобі заспокоєння і полегшення трудів.","При цих словах моїх до неї, несподівано засяяло лице і погляд її, і ось, вигляд зробився блискучим, так що я, переляканий нею, думав, що б це було.","І ось, вона несподівано випустила настільки голосний і настільки страшний звук голосу, що від цього звуку жінки захиталася земля.","І я бачив, і ось, жінка більше не являлася мені, але створювалося місто, і місце його позначалося на великих основах, і я переляканий голосно викликнув і сказав:","де ангел Уриїл, який спочатку приходив до мене? бо він привів мене до такої несамовитости розуму, в якому мета мого прагнення зникла, і молитва моя обернулася на ганьбу.","Коли я говорив це, він прийшов до мене;","і побачив мене, і ось, я лежав, як мертвий і в непритомному стані; він узяв мене за праву руку, укріпив мене і, поставивши на ноги, сказав мені:","що з тобою? від чого збентежені розум твій і почуття серця твого? від чого бентежишся?","Від того, — відповів я йому, — що ти залишив мене, і я, чинячи за словами твоїми, вийшов на поле, і ось побачив і ще бачу те, про що не можу розповісти.","А він сказав мені: стій мужньо, і я поясню тобі.","Говори мені, господарю мій, — сказав я, — тільки не залишай мене, щоб я не помер марно;","бо я бачив, чого не знав, і чув, чого не знаю.","Чи почуття моє обманює мене, чи душа моя марить уві сні?","Тому прошу тебе пояснити мені, рабові твоєму, цю несамовитість розуму мого. Відповідаючи мені, сказав він:","слухай мене, і я навчу тебе, і поясню тобі те, що налякало тебе: бо Всевишній відкриє тобі багато таємниць.","Він бачить правий шлях твій, що ти безперестанно уболіваєш за народ твій і сильно засмучуєшся за Сион.","Таке значення видіння, яке перед цим явилося тобі:","жона, яку ти бачив, що вона плаче, і намагався утішати,","яка потім стала невидимою, але явилося тобі місто, що будується,","і яка тобі розповіла про смерть сина свого, ось що означає:","жона, яку ти бачив, це Сион. А що сказала тобі та, яку ти бачив, як місто, яке тільки будується,","що вона тридцять років була неплідна, цим указується на те, що впродовж тридцяти років у Сионі ще не приносилася жертва.","Після закінчення тридцяти років неплідна народила сина: це було тоді, коли Соломон збудував місто і приніс жертви.","А що вона сказала тобі, що з трудом виховала його, це було перебування у Єрусалимі.","А що син її, як вона сказала тобі, входячи у чертог свій, упав і помер, це було падіння Єрусалима.","І ось, ти бачив подобу її, і як вона уболівала за сина, намагався утішати її у тім, що трапилося: то належало відкрити тобі про це.","Нині ж Всевишній, бачачи, що ти страждаєш душею і всім серцем уболіваєш за нього, показав тобі світлість слави його і красу його.","Для цього-то я повелів тобі жити у полі, де немає дому.","Я знав, що Всевишній покаже тобі це;","для того і повелів, щоб ти прийшов на поле, де не покладено основи дому.","Бо не могла справа людського творіння існувати там, де почало показуватися місто Всевишнього.","Отже, не бійся, і нехай не страшиться серце твоє, але ввійди і подивися на світлість і красу творіння, скільки можуть бачити очі твої.","Після того почуєш, скільки можуть чути вуха твої.","Ти блаженніший за багатьох і покликаний до Всевишнього, як небагато хто.","На завтрашню ніч залишайся тут,","і Всевишній покаже тобі видіння найвеличніших діл, які Він створить для жителів землі в останні дні.","І спав я в ту ніч і у наступну, як він повелів мені."]},{"v":["І бачив я сон, і ось, піднявся з моря орел, у якого було дванадцять крил пернатих і три голови.","І бачив я: ось, він розпростирав крила свої над усією землею, й усі вітри небесні дули на нього і збиралися хмари.","І бачив я, що з пір’я його виходили інші малі пера і з тих виходили ще менші і короткі.","Голови його спочивали, і середня голова була більша за інші голови, але також спочивала з ними.","І бачив я: ось орел літав на крилах своїх і царював над землею і над усіма жителями її.","І бачив я, що все піднебесне було покірне йому, і ніхто не чинив спротиву йому, жодна з тварин, що існують на землі.","І ось, орел став на пазурі свої і випустив голос до пір’я свого і сказав:","не пильнуйте всі разом; спіть кожне на своєму місці, і пильнуйте по черзі,","а голови нехай зберігаються на останній час.","Бачив я, що голос його виходив не з голів його, але зсередини тіла його.","Я порахував малі пера його; їх було вісім.","І ось, із правого боку піднялося одне перо і зацарювало над усією землею,","і коли зацарювало, прийшов кінець його, і не видно стало місця його; потім піднялося інше перо і царювало; це володарювало довгий час.","Коли воно царювало і наблизився кінець його, щоб воно так само зникло, як і перше,","і ось, чутно було голос, що говорить йому:","слухай ти, яке стільки часу володіло землею! ось що я сповіщаю тобі, перш ніж почнеш зникати:","ніхто після тебе не буде володарювати стільки часу, як ти, і навіть половини того.","І піднялося третє перо і володарювало, як і попередні, але зникло і воно.","Так було і з усіма іншими: вони володарювали і потім зникали назавжди.","Я бачив, що за часом із правого боку піднімалися наступні пера, щоб і їм мати начальство, і деякі з них начальствували, але негайно зникали;","деякі ж з них піднімалися, але не одержували начальства.","Після цього не являлися більше дванадцять пер, ні два малих пера;","і не залишилося у тілі орла нічого, крім двох голів, які спочивали, і шести малих пер.","Я бачив, і ось, із шести малих пер відокремилися два і залишилися під головою, яка була з правого боку, а чотири залишалися на своєму місці.","Потім підкрильні пера намагалися піднятися і начальствувати;","і ось, одне піднялося, але негайно зникло;","а наступні зникали ще швидше, ніж попередні.","І бачив я: ось, два пера, які залишилися, намагалися також царювати.","Коли вони намагалися, одна з голів, що спочивали, яка була середньою, пробудилася, і вона була більшою за інші дві голови.","І бачив я, що дві інші голови з’єдналися з нею.","І ця голова, повернувшись з тими, які були з’єднані з нею, пожерла два підкрильних пера, які намагалися царювати.","Ця голова настрашила всю землю і володарювала над жителями землі з великим гнобленням, і утримувала владу на земній кулі більше всіх крил, які були.","Після того я бачив, що і середня голова несподівано зникла, як і крила;","залишалися дві голови, які подібним чином царювали на землі і над її жителями.","І ось, голова з правого боку пожерла ту, яка була з лівого.","І чув я голос, який говорить мені: дивися перед собою, і розмірковуй про те, що бачиш.","І бачив я: ось, ніби лев, який вибіг з лісу і рикає, випустив людський голос до орла і сказав:","слухай, що я буду говорити тобі і що скаже тобі Всевишній:","чи не ти той, що залишився з числа чотирьох тварин, яких Я поставив царювати у віці Моєму, щоб через них прийшов кінець часів тих?","І четверта з них прийшла, перемогла всіх тварин, які були раніше, і тримала вік у великому трепеті і всю вселенну у лютому гнобленні, і з найтяжчим утиском підвладних, і дуже довгий час жила на землі з підступництвом.","Ти судив землю не за правдою;","ти утискував лагідних, кривдив миролюбних, любив неправдомовців, розоряв житла тих, які приносили користь, і руйнував стіни тих, які не робили тобі шкоди.","І зійшла до Всевишнього образа твоя, і гординя твоя — до Кріпкого.","І споглянув Всевишній на часи гордині, і ось, вони закінчилися, і виповнилася міра злодійств її.","Тому зникни ти, орле, зі страшними крилами твоїми, з мерзотними перами твоїми, зі злими головами твоїми, з жорстокими пазурами твоїми і з усім негідним тілом твоїм,","щоб відпочила вся земля і звільнилася від твого насильства, і надіялася на суд і милосердя свого Творця."]},{"v":["Коли лев говорив до орла ці слова, я побачив,","що не з’являлася більше голова, яка залишалася разом з чотирма крилами, які перейшли до неї і піднімалися, щоб царювати, але царство яких було слабке і повне збурювань.","І я бачив, і ось вони зникли, і все тіло орла згорало, і жахнулася земля, і я від тривоги, несамовитости розуму і від великого страху прокинувся і сказав духу моєму:","ось, ти заподіяв мені це тим, що випробовуєш путі Всевишнього.","Ось, я ще тремчу серцем і дуже знеміг духом моїм, і немає у мені ніскільки сили від великого страху, яким я уражений у цю ніч.","Отже, нині я помолюся Всевишньому, щоб Він укріпив мене до кінця.","І сказав я: Владико Господи! якщо я знайшов благодать перед очима Твоїми, якщо Ти знайшов мене праведним перед багатьма, і якщо молитва моя справді зійшла перед лице Твоє,","укріпи мене і покажи мені, рабові Твоєму, значення цього страшного видіння, щоб цілком заспокоїти душу мою:","бо Ти судив мене гідним, щоб показати мені останні часи. І Він сказав мені:","таке значення видіння цього:","орел, якого ти бачив, що піднімався від моря, є царство, показане у видінні Даниїлові, братові твоєму;","але йому не було пояснено те, що нині Я пояснюю тобі.","Ось, приходять дні, коли постане на землі царство більш страшне, ніж усі царства, які були раніше нього.","У ньому будуть царювати, один після одного, дванадцять царів.","Другий з них почне царювати, і утримає владу більш тривалий час, ніж інші дванадцять.","Таке значення дванадцяти крил, бачених тобою.","А що ти чув голос, який говорив, що виходив не від голів орла, але зсередини тіла його,","це означає, що після часу того царства відбудуться чималі чвари, і царство буде піддане небезпеці падіння; але воно не впаде тоді і відновиться у первісному стані своєму.","А що ти бачив вісім малих підкрильних пер, з’єднаних із крилами, це означає,","що постануть у царстві вісім царів, часи яких будуть легкі і роки швидкоплинні, і два з них загинуть.","Коли буде наближатися середній час, чотири збережуться до того часу, коли буде близький кінець його; а два збережуться до кінця.","А що ти бачив три голови, які спочивають, це означає,","що в останні дні царства Всевишній воздвигне три царства і підкорить їм багато інших, і вони будуть володарювати над землею і жителями її","з більшим утиском, ніж усі, що були раніше; тому вони і названі головами орла,","бо саме вони довершать беззаконня його і покладуть кінець йому.","А що ти бачив, що велика голова не з’являлася більше, це означає, що один з царів помре на постелі своїй, втім, з муками,","а двох інших пожере меч;","меч одного пожере того, який з ним, але і він з часом помре від меча.","А що ти бачив, два підкрильних пера перейшли на голову, яка знаходиться з правого боку,","це ті, яких Всевишній зберіг до кінця царства, тобто царство убоге і сповнене занепокоєнь.","Лев, якого ти бачив, як він піднявся з лісу і рикав, який говорив до орла й викривав його у неправдах його всіма словами його, які ти чув,","це — Помазаник, збережений Всевишнім до кінця проти них і нечестя їх, Який викриє їх і представить перед ними утиски їх.","Він поставить їх на суд живих і, викривши їх, покарає їх.","Він з милосердя визволить залишок народу Мого, тих, які збереглися у межах Моїх, і обрадує їх, доки не прийде кінець, день суду, про який Я сказав тобі на початку.","Такий сон, бачений тобою, і таке значення його.","Ти один був достойний знати цю таємницю Всевишнього.","Усе це, бачене тобою, напиши у книзі і поклади у потаємному місці;","і навчи цього мудрих з народу твого, яких серця́ ви́знаєш здатними прийняти і зберігати ці таємниці.","А ти пробудь тут ще сім днів, щоб тобі показано було, що Всевишньому вгодно буде показати тобі. І відійшов від мене.","Коли після закінчення семи днів весь народ почув, що я не повернувся у місто, зібралися всі від малого до великого і, прийшовши до мене, говорили мені:","чим згрішили ми проти тебе? І чим скривдили тебе, що ти, залишивши нас, сидиш на цьому місці?","Ти один із усього народу залишився нам, як гроно від винограду, як світильник у темному місці і як пристань і корабель, урятований від бурі.","Невже мало бід, що сталися з нами?","Якщо ти залишиш нас, то краще було б для нас згоріти, коли горів Сион.","Бо ми не кращі за тих, які померли там. І плакали вони з голосним воланням. Відповідаючи їм, я сказав:","надійся, Ізраїлю, і не тужи, доме Якова;","бо пам’ятає про вас Всевишній, і Кріпкий не забув вас у напасті.","І я не залишив вас і не пішов від вас, але прийшов на це місце, щоб помолитися за розорений Сион і просити милосердя приниженій святині вашій.","Тепер ідіть кожен у дім свій, і я прийду до вас після цих днів.","І пішов народ, як я сказав йому, у місто,","а я залишався у полі протягом семи днів, як повелено мені, і годувався у ті дні тільки квітами польовими, і трава була мені їжею."]},{"v":["І було після семи днів, я бачив уночі сон:","ось, піднявся вітер з моря, щоб збурити всі хвилі його.","Я дивився, і ось, вийшов кріпкий муж з воїнством небесним, і куди б він не повертав лице своє, щоб глянути, все тремтіло, що виднілося під ним;","і куди б не виходив голос з уст його, загорялися всі, які чули голос його, подібно до того, як тане віск, коли відчує вогонь.","І після цього бачив я: ось, зібралася безліч людей, яким не було числа, від чотирьох вітрів небесних, щоб перебороти цього мужа, який піднявся з моря.","Бачив я, і ось, він виліпив собі велику гору і злетів на неї.","Я намагався побачити ту країну або місце, звідки виліплена була ця гора, але не міг.","Після цього бачив я, що всі, які зібралися перемогти його, дуже злякалися й, однак же, насмілилися воювати.","Він же, коли побачив поривання безлічі, яка йшла, не підняв руки своєї, ні списа не тримав, і ніякої зброї військової;","але тільки, як я бачив, він випускав з уст своїх ніби подув вогню і з губ своїх — ніби подих полум’я і з язика свого пускав іскри і бурі, і все це змішалося разом: і подув вогню і подих полум’я і сильна буря.","І стрімко напав він на цю безліч, яка приготувалася воювати, і спалив усіх, так що нічого не видно було з незліченної безлічі, крім пороху, і тільки був запах від диму; побачив я це, і настрашився.","Після цього я бачив того мужа, що сходив з гори і закликав до себе іншу безліч, мирну.","І багато хто приступав до нього, деякі з лицями веселими, а деякі із сумними, деякі були зв’язані, деяких приносили, — і я знеміг від великого страху, прокинувся і сказав:","Ти від початку показав рабові Твоєму чудеса ці і судив мене достойним, щоб прийняти молитву мою;","покажи ж мені і значення сну цього,","тому що, як я розумію розумом моїм, горе тим, які залишені будуть до тих днів, а ще більше горе тим, які не залишені.","Бо ті, які не залишені, були сумні.","Тепер я розумію, що те, що відкладено на останні дні, зустріне їх, але і тих, які залишені.","Тому вони прийшли у великі небезпеки і великі утруднення, як показують ці сни.","Але легше тому, хто знаходиться у небезпеці, перетерпіти це, ніж перейти, подібно до хмари, із світу цього і не бачити того, що буде в останні часи. Він відповів мені і сказав:","І значення видіння Я скажу тобі, і про що ти говорив, відкрию тобі.","Оскільки ти говорив про тих, які залишені, то ось пояснення:","хто витримає небезпеку у той час, той зберіг себе, а ті, які впадуть у небезпеку, це ті, які мають діла і віру у Всемогутнього.","Отже, знай, що ті, які залишені, блаженніші за померлих.","Ось пояснення видіння: оскільки ти бачив мужа, який виходив із середини моря,","це той, якого Всевишній зберігає багато часів, який самим собою визволить творіння Своє й управить тих, які залишені.","А що ти бачив ніби вітер, вогонь і бурю, які виходили із уст його,","і що він не тримав ні списа і ніякої військової зброї, але спрямування його уразило безліч, яка прийшла, щоб перемогти його, то ось пояснення:","ось, настають дні, коли Всевишній почне спасати тих, які на землі,","і приведе у здивування тих, що живуть на землі.","І будуть починати війни одні проти одних, місто проти міста, одне місце проти іншого, народ проти народу, царство проти царства.","Коли це буде і з’являться знамення, які Я показав тобі раніше, тоді відкриється Син Мій, Якого ти бачив, як мужа, який сходить.","І коли всі народи почують голос Його, кожен облишить війну у своїй власній країні, яку вони мають між собою.","І збереться в одне зібрання безліч незліченна, ніби бажаючи йти і перемогти Його.","Він же стане на верху гори Сион.","І Сион прийде і покажеться усім приготований і влаштований, як ти бачив гору, виліплену без рук.","Син же Мій викриє нечестя, винайдені цими народами, які своїми злими помислами наблизили бурю і муки, якими вони почнуть мучитися,","і які подібні до вогню; і Він знищить їх без великих зусиль законом, який подібний до вогню.","А що ти бачив, що Він збирав до себе іншу, мирну громаду:","це десять колін, які відведені були полоненими з землі своєї у дні царя Осії, якого відвів у полон Салманассар, цар Ассирійський, і перевів їх за ріку, і переведені були у землю іншу.","Вони ж поклали у раді своїй, щоб залишити безліч язичників і вирушити у далеку країну, де ніколи не жив рід людський,","щоб там дотримуватися законів своїх, яких вони не дотримувалися у країні своїй.","Тісними входами підійшли вони до ріки Євфрату;","бо Всевишній створив тоді для них чудеса і зупинив жили ріки, доки вони проходили;","бо через цю країну йшли вони довго, півтора року; ця країна називається Арсареф.","Там жили вони до останнього часу. І нині, коли вони почнуть приходити,","Всевишній знову зупинить жили ріки, щоб вони могли пройти; тому ти бачив безліч мирну.","Але ті, які залишені від народу твого, це ті, які знаходяться всередині меж Моїх.","Бо, коли Він почне знищувати безліч народів, які зібралися разом, Він захистить народ Свій, який залишиться.","І тоді покаже їм безліч чудес.","Я сказав: Владико Господи! Поясни мені це, для чого бачив я мужа, який виходив із середини моря?","І Він сказав мені: як не можеш ти дослідити і пізнати того, що у глибині моря, так ніхто не може на землі бачити Сина Мого, ні тих, які з Ним, хіба тільки під час дня Його.","Ось тлумачення сну, який ти бачив і яким ти один тут просвічений.","Ти залишив діла твої і вправлявся у законі Моєму, і знайшов його,","бо життя твоє ти влаштував у мудрості і розсудливість назвав твоєю матір’ю.","Тому Я показав тобі винагороди у Всевишнього: після трьох днів Я покажу тобі інше і відкрию тобі важливе і дивне.","Тоді я пішов і вийшов у поле, багато славлячи і дякуючи Всевишньому за чудеса, які Він звершував часами,","і що Він управляє теперішнім і тим, що відбудеться в часі, — і там я сидів три дні."]},{"v":["І було після трьох днів, я сидів під дубом, і ось, голос вийшов з куща навпроти мене і сказав: Ездро, Ездро!","Я сказав: ось я, Господи. І встав на ноги мої.","Тоді сказав Він мені: у кущі Я відкрився і говорив Мойсеєві, коли народ Мій був рабом у Єгипті;","і послав його і вивів народ Мій з Єгипту, і привів його до гори Синаю і тримав його у Себе багато днів,","і відкрив йому багато чудес і показав таємниці часів і кінець, і заповів йому, сказавши:","«Ці слова оголоси, а інші приховай».","І нині тобі говорю:","знамення, які Я показав тобі, і сни, які ти бачив, і тлумачення, які чув, поклади у серці твоєму;","бо ти взятий будеш від людей і будеш знаходитися із Сином Моїм і з подібними до тебе, доки не закінчаться часи.","Бо вік утратив свою юність, і часи наближаються до старости,","оскільки вік розділений на дванадцять частин, і дев’ять частин його і половина десятої частини вже минули,","і залишається те, що після половини десятої частини.","Отже, нині влаштуй дім твій і напоум народ твій, утіш принижених і зречися тління,","і відпусти від себе смертні помисли, відкинь тягарі людські, зніми із себе немочі єства і відклади вбік тяжкі для тебе помисли, і готуйся переселитися від часів цих.","Бо після більше буде бід, ніж скільки ти бачив нині.","Скільки буде слабшати вік від старости, стільки буде збільшуватися зло для тих, що живуть.","Ще далі відійде істина, і наблизиться неправда; уже поспішає прийти видіння, яке ти бачив.","Тоді відповів я і сказав: ось, я — перед Тобою, Господи;","я піду, як Ти повелів мені, й напоумлю нинішній народ; але хто навчить тих, які потім народяться?","Бо вік у пітьмі лежить, і ті, що живуть у ньому, — без світла;","тому що закон Твій спалений, і від того ніхто не знає, що зроблено Тобою або що слід їм робити.","Але якщо я придбав милість у Тебе, зішли на мене Духа Святого, щоб я написав усе, що було зроблено у світі від початку, що було написано у законі Твоєму, щоб люди могли знайти путь і щоб ті, які захочуть жити в останні часи, могли жити.","І Він у відповідь сказав мені: йди, збери народ і скажи йому, щоб він не шукав тебе протягом сорока днів.","Ти ж приготуй собі побільше дощечок і візьми із собою Сарія, Даврія, Салемія, Ехана й Асиеля, цих п’ятьох, здатних писати швидко.","І прийди сюди, і Я запалю у серці твоєму світильник розуму, який не згасне, доки не закінчиться те, що ти почнеш писати.","І коли ти звершиш це, то дещо оголоси, а дещо таємно передай мудрим. Завтра у цю годину ти почнеш писати.","Тоді я пішов, як Він повелів мені, і зібрав весь народ і сказав:","слухай, Ізраїлю, слова ці:","батьки наші були подорожніми у Єгипті, і були визволені звідти,","і прийняли закон життя, якого не зберегли, який і ви після них порушили.","І дана була вам земля у спадщину і земля Сион; але батьки ваші і ви робили беззаконня і не трималися тих шляхів, які Всевишній заповів вам.","І Він, як праведний суддя, відняв у вас нині, що дарував вам.","І нині ви тут і брати ваші між вами.","Якщо ви будете управляти почуттям вашим і впорядкуєте серце ваше, то збережете життя і після смерти одержите милість.","Бо після смерти настане суд, коли ми оживемо; і тоді імена праведних будуть оголошені й показані діла нечестивих.","Ніхто не приходь до мене нині і не шукай мене до сорока днів.","І взяв я п’ятьох мужів, як Він заповів мені, і пішли ми у поле і залишилися там.","І ось, на другий день голос воззвав до мене: Ездро! відкрий уста твої і випий те, чим Я напою тебе.","Я відкрив уста мої, і ось повна чаша подана була мені, яка була наповнена ніби водою, але колір того був подібний до вогню.","І взяв я і пив; і коли я пив, серце моє дихало розумом і у грудях моїх зростала мудрість, бо дух мій підкріплювався пам’яттю;","вуста мої були відкриті і більше не закривалися.","Всевишній дарував розум п’ятьом мужам, і вони вночі писали по порядку, що було говорено їм і чого вони не знали.","Вночі вони їли хліб; а я говорив удень і не мовчав уночі.","Написані ж були за сорок днів дев’яносто чотири книги.","І коли виповнилося сорок днів,","Всевишній сказав: перші, які ти написав, поклади відкрито, щоб могли читати достойні і недостойні,","але останні сімдесят збережи, щоб передати їх мудрим з народу;","бо у них провідник розуму, джерело мудрости і ріка знання. Так я і зробив."],"x":{"4":"4.5.6","30":"4.4.6"}},{"v":["Говори, щоб чув народ Мій слова пророцтва, які вкладу Я у вуста твої, — говорить Господь;","і зроби, щоб вони написані були на хартії, тому що вони вірні й істинні.","Не бійся, що будуть замишляти проти тебе, і нехай не бентежить тебе невір’я тих, які будуть говорити проти тебе,","бо всякий невіруючий у невір’ї своєму помре.","Ось, Я наведу, — говорить Господь, — на коло земне біди: меч і голод, і смерть і пагубу","за те, що нечестя людей осквернило всю землю, і пагубні діла їхні переповнилися.","Тому говорить Господь:","Я вже не буду мовчати про беззаконня, які звершують вони нечестиво, і не буду терпіти у них того, що вони роблять злочинно: ось, кров невинна і праведна волає до Мене, і душі праведних взивають безперестанно.","Помщуся їм, — говорить Господь, — і візьму від них до Себе всяку кров невинну.","Ось, народ Мій ведеться, як стадо на заколення; не потерплю більше, щоб він жив у Єгипті,","але виведу його рукою сильною і правицею високою, й уражу Єгипет карою, як колись, і погублю всю землю його.","Заплаче Єгипет і основи його, уражені стратою і помстою, яку наведе на нього Бог.","Заплачуть хлібороби, які обробляють землю, бо занепаде у них насіння від іржі й від граду і від страшної зірки.","Горе віку і тим, які живуть у ньому,","бо наблизився меч і знищення їх, і постане народ на народ для війни, і мечі у руках їх.","Люди зробляться непостійними і, одні одних долаючи, будуть недбалими до царя свого, і начальники — до ходу справ своїх у межах своєї влади.","Побажає людина йти у місто, і не зможе,","бо, через їхню гордість, міста обуряться, доми будуть розорені, на людей нападе страх.","Не зглянеться людина на ближнього свого, віддаючи доми їх на розорення зброєю, розкрадаючи майно їх з причини голоду і багатьох бід.","Ось, Я скликаю, — говорить Бог, — усіх царів землі, від сходу і півдня, від півночі і Ливану, щоб благоговіли переді Мною і навернулися до себе самих, і щоб воздати їм, що вони робили тим.","Як чинять вони навіть дотепер з обраними Моїми, так учиню з ними і воздам у надро їх, — говорить Господь Бог.","Не пощадить правиця Моя грішників, і меч не перестане уражати тих, що проливають на землю невинну кров.","Зійшов вогонь від гніву Його і знищив основи землі і грішників, як запалену солому.","Горе грішникам і тим, що не дотримуються заповідей Моїх! — говорить Господь.","Не пощаджу їх. Відійдіть, сини відступників, не оскверняйте святині Моєї.","Господь знає всіх, які грішать проти Нього; тому віддав їх на смерть і на вбиття.","На коло земне прийшли вже біди, і ви перебуватимете у них. Бог не визволить вас, тому що ви згрішили проти Нього.","Ось, видіння грізне, і лице його від сходу.","Виступлять породження драконів аравійських на багатьох колісницях і зі швидкістю вітру понесуться по землі, так що наведуть страх і трепет на всіх, які почують про них.","Вийдуть, як вепри з лісу, кармоняни, які шаленіють у люті, і прийдуть у великій силі, вступлять у боротьбу з ними і спустошать частину землі Ассирійської.","Потім дракони, які пам’ятають походження своє, візьмуть гору і, володіючи великою силою, повернуться переслідувати тих.","Ті збентежаться, замовкнуть перед силою їх і повернуть ноги свої на втечу.","Але той, що знаходиться у засідці з боку ассиріян, оточить їх і умертвить одного з них; у війську їх виникнуть страх і трепет і ремство на царів їх.","Ось, хмари від сходу і від півночі до півдня, і вигляд їх дуже грізний, сповнений лютости і бурі.","Вони зіштовхнуться між собою, і скинуть багато зірок на землю і зірку їх; і буде кров від меча до черева,","і послід людський — до сідла верблюда; страх і трепет великий буде на землі.","Жахнуться всі, які побачать цю лютість, і затремтять.","Після того багато разів будуть підніматися бурі від півдня і півночі і частково від заходу,","і вітри сильні здіймуться від сходу і відкриють його і хмару, яку Я послав у гніві; а зірка, призначена для страху при східному і західному вітрі, пошкодиться.","І піднімуться хмари, великі і сильні, повні лютости, і зірка, щоб настрашити всю землю і жителів її; і проллють на всяке місце, високе і піднесене, страшну зірку,","вогонь і град, мечі, що літають, і багато вод, щоб наповнити всі поля і всі джерела безліччю вод.","І затоплять місто, і стіни, і гори, і пагорби, і дерева у лісах, і траву на луках, і хлібні рослини їх;","і пройдуть, не спиняючись, до Вавилона і знищать його;","зберуться до нього й оточать його; проллють зірку і лють на нього. І підніметься пил і дим до самого неба, і всі навкруги будуть оплакувати його,","а ті, які залишаться підвладними йому, будуть служити тим, що навели страх.","І ти, Асіє, співучаснице у надії Вавилона й у славі його:","горе тобі, бідна, за те, що уподібнювалася йому і прикрашала дочок твоїх у блудодіянні, щоб вони подобалися і славилися у коханців твоїх, які бажали завжди блудодіяти з тобою.","Ти наслідувала ненависного в усіх ділах і заходах його.","За те, — говорить Бог, — пошлю на тебе біди: удівство, убогість, і голод, і меч, і моровицю, щоб спустошити доми твої насильством і смертю.","І слава могутности твоєї засохне, як квітка, коли настане спека, послана на тебе.","Ти знеможеш, як убога, побита і поранена жінками, щоб люди знатні і коханці не могли приймати тебе.","Чи став би Я так ненавидіти тебе, — говорить Господь, —","якби ти не убивала обраних Моїх повсякчас, піднімаючи руки на поразку їх і глумлячись зі смерти їх, коли ти була у сп’янінні?","Прикрашай твоє лице.","Мзда блудодіяння твого у надрі твоєму; за те й одержиш ти винагороду.","Як чинила ти з обраними Моїми, — говорить Господь, — так з тобою вчинить Бог, і піддасть тебе бідам.","Діти твої загинуть від голоду, ти впадеш від меча, міста твої будуть зруйновані, і всі твої впадуть у полі від меча.","А які на горах, ті загинуть від голоду, і будуть їсти плоть свою через нестачу хліба і пити кров через нестачу води.","У нещасті підеш по морях, — і там зустрінеш біди.","Під час переходів твоїх вони кинуться на спустошене місто, і знищать частину землі твоєї, і частину слави твоєї знищать.","Розорена, ти послужиш для них соломою, а вони для тебе будуть вогнем;","і знищать тебе, і міста твої, землю твою, гори твої, усі ліси твої і дерева родючі спалять вогнем.","Синів твоїх поведуть у полон, майно твоє захоплять у здобич, і славу твою знищать."]},{"v":["Горе тобі, Вавилоне й Асіє, горе тобі, Єгипте і Сиріє!","Підпережіться веретищем і волосяницями, оплакуйте синів ваших, і уболівайте, бо наблизилася ваша погибель.","Посланий на вас меч, — і хто відхилить його?","Посланий на вас вогонь, — і хто погасить його?","Послані на вас біди, — і хто відверне їх?","Чи прожене хто голодного лева у лісі, або чи погасить миттєво вогонь у соломі, коли він почне розгорятися?","Чи відіб’є хто стрілу, пущену стрільцем сильним?","Господь сильний посилає біди, — і хто відверне їх?","Зійшов вогонь від гніву Його, — і хто погасить його?","Він блисне блискавкою, — і хто не убоїться? Прогримить, — і хто не жахнеться?","Господь спогляне грізно, — і хто не знищиться до основи від лиця Його?","Здригнулася земля і основи її; море хвилюється з дна, і хвилі його збурюються і риби його від лиця Господа і від величі сили Його.","Бо сильна Його правиця, яка натягає лук, гострі Його стріли, які пускаються Ним, не ослабнуть, коли будуть посилатися до країв землі.","Ось, посилаються біди, і не повернуться, доки не прийдуть на землю.","Розгоряється вогонь, і не погасне, доки не попалить основи землі.","Як стріла, пущена сильним стрільцем, не повертається, так не повернуться біди, які будуть послані на землю.","Горе мені, горе мені! Хто визволить мене у ті дні?","Почнуться хвороби, — і багато хто застогне; почнеться голод, — і багато хто буде гинути; почнуться війни, — і начальниками оволодіє страх; почнуться біди, — і всі затремтять.","Що мені робити тоді, коли прийдуть біди?","Ось, голод і моровиця, і скорбота і тіснота послані як бичі для виправлення:","але при всьому цьому люди не навернуться від беззаконь своїх і про бичі не завжди будуть пам’ятати.","Ось, на землі буде дешевизна в усьому, і подумають, що настав мир; але саме тоді й спіткають землю біди — меч, голод і велике сум’яття.","Від голоду загинуть дуже багато жителів землі, а інші, які перенесуть голод, упадуть від меча.","І трупи, як гній, будуть викидати, і нікому буде оплакувати їх, бо земля спорожніє, і міста її будуть зруйновані.","Не залишиться нікого, хто обробляв би землю і сіяв на ній.","Дерева дадуть плоди, і хто буде збирати їх?","Виноград дозріє, і хто буде топтати його? Бо всюди буде велике запустіння.","Важко буде людині побачити людину, або почути голос її,","бо з жителів міста залишиться не більше десяти, і з поселенців — чоловіка два, які сховаються у густих дібровах і розщелинах скель.","Як у оливковому саду залишаються іноді на деревах три або чотири маслини,","або у винограднику обібраному не догледять кілька грон ті, які уважно оббирають виноград:","так у ті дні залишаться троє або четверо під час обшуку домів їхніх з мечем.","Земля залишиться у запустінні, поля її заглухнуть, дороги її і всі стежини її заростуть терням, бо нікому буде ходити по них.","Плакати будуть дівчата, не маючи наречених; плакати будуть дружини, не маючи чоловіків; плакати будуть дочки їхні, не маючи допомоги.","Наречених їхніх уб’ють на війні, і чоловіки їхні загинуть від голоду.","Слухайте це, і напоумляйтесь, раби Господні!","Це — слово Господа: слухайте його, і не вірте богам, про яких говорить Господь.","Ось, наближаються біди, і не забаряться.","Як у вагітної жінки, коли у дев’ятий місяць настане їй час народити сина, години за дві або за три до народження, болі охоплюють утробу її і, при виході немовляти з утроби, не забаряться на жодну хвилину:","так не забаряться прийти на землю біди, і люди у той час будуть стогнати; болі охоплять їх.","Слухай слово, народе мій: готуйтеся на битву, і серед бід будьте як пришельці землі.","Хто продає, нехай буде, як той, що збирається на втечу, і хто купує — як той, що готується на загибель;","хто торгує — як той, що не очікує ніякого прибутку, і хто будує дім — як той, що не сподівається жити у ньому.","Сівач нехай думає, що не пожне, і виноградар — що не збере винограду;","ті, що вступають у шлюб, — що не будуть народжувати дітей, і ті, що не вступають, — як удівці.","Тому всі трудящі без користи трудяться,","бо плодами трудів їхніх скористаються чужоземці, і майно їхнє розкрадуть, доми їхні зруйнують, синів їхніх поневолять, бо у полоні і в голоді вони народжують дітей своїх.","Хто займається хижацтвом, тих, чим довше прикрашають вони міста і доми свої, володіння і лиця свої,","тим більше зненавиджу за гріхи їхні, — говорить Господь.","Як блудниця ненавидить жінку чесну і дуже побожну,","так правда зненавидить неправду, що прикрашає себе, і звинуватить її у лице, коли прийде Той, Хто буде захищати того, хто переслідує всякий гріх на землі.","Тому не наслідуйте неправду і діла її,","бо ще трохи, і неправда буде вилучена з землі, а правда зацарює над вами.","Нехай не говорить грішник, що він не згрішив, бо розпалене вугілля запалає на голові того, хто говорить: я не згрішив перед Господом Богом і славою Його.","Господь знає всі діла людей і починання їхні, і помисли їхні і серця їхні.","Він сказав: «нехай буде земля», — і земля з’явилася; «нехай буде небо», — і було.","Словом Його створені зірки, і Він знає число зірок.","Він споглядає безодні й потаємне у них, виміряв море і що у ньому.","Словом Своїм Він утворив море серед вод і землю повісив на водах.","Він розпростер небо, як намет, на водах заснував його.","Він вмістив у пустелі джерела вод і озера на вершинах гір, для зведення рік з високих скель, щоб напоювати землю.","Він створив людину і поклав серце її всередині тіла, і вклав у неї дух, життя і розум","і дихання Бога всемогутнього, Який створив усе і споглядає все потаємне у потаємних землі.","Він знає намір ваш і що думаєте ви у серцях ваших, коли грішите і хочете сховати гріхи ваші.","Тому Господь зовсім ясно бачить усі діла ваші, і викриє усіх вас;","і ви будете посоромлені, коли гріхи ваші відкриються перед людьми, і беззаконня стануть звинувачувати у той день.","Що ви зробите і як сховаєте гріхи ваші перед Богом і ангелами Його?","Ось, Бог — Суддя; бійтеся Його; залиште гріхи ваші і назавжди перестаньте чинити беззаконня, і Бог виведе вас і визволить від усякої скорботи.","Бо ось, запалюється на вас лють численного полчища, і схоплять деяких з вас і умертвлять для принесення в жертву ідолам.","Хто буде єдинодумним з ними, тих піддадуть вони посміянню, ганьбі і потоптанню.","Бо по всіх місцях і у сусідніх містах багато хто повстане проти тих, які бояться Господа.","Будуть, як несамовиті, без пощади розкрадати і спустошувати все у тих, які бояться Господа.","Спустошать і розкрадуть майно їх, і з домів їхніх виженуть їх.","Тоді настане випробування обраним Моїм, як золото випробовується вогнем.","Слухайте, улюблені Мої, — говорить Господь: ось перед вами дні скорботи, і від них Я визволю вас.","Не бійтеся і не сумнівайтеся, бо вождь ваш — Бог.","Якщо будете виконувати заповіді і повеління Мої, — говорить Господь Бог, — то гріхи ваші не будуть тягарем, що придушує вас, і беззаконня ваші не переможуть вас.","Горе тим, які зв’язані гріхами своїми і покриті беззаконнями своїми! Це — поле, яке заросло чагарником і через яке путь покритий терням, так що людина проходити не може: воно залишається і віддається вогню на знищення."]}];
export default C;
